function player(id){return master.players.find(x=>x.id===id)||state.quickPlayers?.[id]} function team(id){return master.teams.find(x=>x.id===id)} function season(id){return master.seasons.find(x=>x.id===id)} function matchType(id){return master.matchTypes.find(x=>x.id===id)}
