async function rotate(dir=1,log=true,side=null,eventGroup=''){
 if(!matchConfigured()){setStatus('Bitte zuerst das Spiel einrichten.');return}
 side=side||activeSide();
 const own=side==='own';
 const old={...lineupForSide(side)};
 const oldIndex=rotationIndexForSide(side);
 // I–VI/P1–P6 sind feste Feldpositionen. Nur Spieler-ID, Trikotnummer und Name wandern.
 const next=rotatedLineup(old,dir);
 if(own){state.ownLineup=next;state.rotationIndex=(state.rotationIndex+(dir>0?1:5))%6}
 else{state.oppLineup=next;state.oppRotationIndex=((state.oppRotationIndex||0)+(dir>0?1:5))%6}
 const newIndex=rotationIndexForSide(side);
 persist();render();
 if(log)await appendEvent('','',`${own?'':'Gegner '}${dir>0?'Rotation weiter':'Rotation zurück'}`,ROT[newIndex],'',{rotation_side:side,rotation_index_before:String(oldIndex),rotation_index_after:String(newIndex),lineup_before:JSON.stringify(old),lineup_after:JSON.stringify(next),event_group:eventGroup||newId('grp')});
 setStatus(`${own?'Eigenes Team':'Gegner'} · ${ROT[newIndex]} · Rotation ${dir>0?'weiter':'zurück'}.`)
}
