 if(isMatchFinishedAfterSet(finished,state.setWinsUs,state.setWinsThem)){state.matchComplete=true;state.setReady=false;persist();render();setStatus(`Spiel beendet · Sätze ${state.setWinsUs}:${state.setWinsThem}. Livezeit gestoppt.${clockWarning}`);return}
