 b.innerHTML=`<div class="card quick-scout-card"><div class="analysis-heading"><h3>Spontanes Scouting <span class="preview-pill">0.3 Preview</span></h3><p class="small">Ohne vorherige Anlage von Spielerinnen, Saison, Match oder Gegner. Auswertung bleibt auf dieses Match begrenzt. Long-Touch auf eine Feldposition setzt Trikotnummer/Beschreibung.</p></div><div class="toolbar"><button class="primary" id="quickScoutStart">Spontanes Scouting starten</button></div></div><div class="card"><div class="form-grid"><label>Spieldatum</label><input id="mDate" type="date" value="${esc(state.matchDate||new Date().toISOString().slice(0,10))}"><label>Saison</label><select id="mSeason"><option value="">–</option>${opts(seas,state.seasonId)}</select><label>Eigenes Team</label><select id="mOwn"><option value="">–</option>${opts(owns,state.ownTeamId)}</select><label>Gegner</label><select id="mOpp"><option value="">–</option>${opts(opps,state.oppTeamId)}</select><label>Spiel-/Kaderart</label><select id="mType"><option value="__quick__" ${state.quickScout?'selected':''}>Spontanes Scouting</option>${types.map(n=>`<option value="${esc(n)}" ${!state.quickScout&&n===(matchType(state.matchTypeId)?.name||state.matchTypeName||'Punktspiel')?'selected':''}>${esc(n)}</option>`).join('')}</select><label>Spielmodus</label><select id="mMatchMode"><option value="regular" ${state.matchMode!=='fixed'?'selected':''}>Regulär · 3 Gewinnsätze (max. 5)</option><option value="fixed" ${state.matchMode==='fixed'?'selected':''}>Feste Anzahl Sätze</option></select><label class="fixed-set-option">Anzahl Sätze</label><select id="mFixedSetCount" class="fixed-set-option">${[1,2,3,4,5].map(n=>`<option value="${n}" ${+state.fixedSetCount===n?'selected':''}>${n}</option>`).join('')}</select><label class="fixed-set-option">Letzter Satz</label><select id="mFixedFinalTarget" class="fixed-set-option"><option value="25" ${+state.fixedFinalSetTarget!==15?'selected':''}>normal bis 25</option><option value="15" ${+state.fixedFinalSetTarget===15?'selected':''}>verkürzt bis 15</option></select></div><div class="quality-switches"><label class="switch-row"><span>Gegner mitscouten / Startaufstellung erfassen</span><span class="switch"><input type="checkbox" id="mCaptureOpponent" ${state.opponentCapture?'checked':''}><span class="slider"></span></span></label><label class="switch-row"><span>Eigenes Team · detaillierte Bewertung</span><span class="switch"><input type="checkbox" id="mOwnDetailed" ${ownDetailed?'checked':''}><span class="slider"></span></span></label><small>= / - / / / 0 / + / ++</small><label class="switch-row"><span>Gegner · detaillierte Bewertung</span><span class="switch"><input type="checkbox" id="mOppDetailed" ${oppDetailed?'checked':''}><span class="slider"></span></span></label><small>= / - / / / 0 / + / ++</small></div><div class="toolbar mt"><button class="primary" id="applyMatch">Spiel übernehmen</button><button id="prepareSet">${state.setReady?`Satz ${state.setNo} neu vorbereiten`:`Satz ${state.setNo} vorbereiten`}</button>${state.setReady?'<button id="lineupOwn">Aufstellung Wir ändern</button>':''}${state.setReady&&state.opponentCapture?'<button id="lineupOpp">Aufstellung Gegner ändern</button>':''}<button class="danger" id="resetScouting">Scouting zurücksetzen</button></div></div><div class="card small">Die Team-Stammdaten liefern nur den Standard. Spielmodus, Satzanzahl und Bewertungs-/Gegnereinstellungen gelten für dieses Spiel und werden im Spielzustand sowie in neuen CSV-Ereignissen gespeichert.</div>`;
 $('#quickScoutStart').onclick=startQuickScout;const mtSel=$('#mType');if(mtSel)mtSel.onchange=()=>changeMatchTypeFromUi(mtSel.value);
 const syncSwitchDefaults=()=>{const own=$('#mOwn').value,opp=$('#mOpp').value;if(own)$('#mOwnDetailed').checked=qualityProfileForTeam(own)==='datavolley_6';if(opp)$('#mOppDetailed').checked=qualityProfileForTeam(opp)==='datavolley_6'};
 $('#mOwn').addEventListener('change',syncSwitchDefaults);$('#mOpp').addEventListener('change',syncSwitchDefaults);const syncMatchModeFields=()=>{$$('.fixed-set-option').forEach(el=>el.hidden=$('#mMatchMode').value!=='fixed')};$('#mMatchMode').addEventListener('change',syncMatchModeFields);syncMatchModeFields();
 $('#mCaptureOpponent').addEventListener('change',e=>{state.opponentCapture=!!e.currentTarget.checked;if(!state.opponentCapture&&state.activeTeamContext==='opponent')state.activeTeamContext='own';persist();render();setStatus(state.opponentCapture?'Gegner-Scouting aktiviert. Die Gegneraufstellung wird bei der Satzvorbereitung abgefragt.':'Gegner-Scouting deaktiviert. Bei der Satzvorbereitung wird nur unsere Aufstellung abgefragt.')});
